export function getToolPageData(slug: string): ToolPageData | undefined {
  return toolPages.find((t) => t.slug === slug);
}

export function isPublished(slug: string): boolean {
  const p = toolPages.find((t) => t.slug === slug);
  return !!p && p.status !== 'draft';
}

export function getModelPriceLabel(slug: string): string | undefined {
  const p = toolPages.find((t) => t.slug === slug);
  if (!p) return undefined;
  const tool = p.tool;
  const pricing = tool?.pricing;
  let min: number | undefined;
  if (pricing) {
    if (typeof pricing.minCredits === "number") {
      min = pricing.minCredits;
    } else {
      const rates = pricing.rates ?? [];
      if (rates.length) min = Math.min(...rates.map((r) => r.rate));
    }
  }
  if (min === undefined && typeof tool?.credits === "number") min = tool.credits;
  return typeof min === "number" ? `от ${min} кр` : undefined;
}

export function getRelatedTools(slug: string, limit = 6): ToolPageData[] {
  const current = toolPages.find((t) => t.slug === slug);
  if (!current) return [];
  const withTool = toolPages.filter((t) => t.slug !== slug && t.tool);
  const sameCat = withTool.filter((t) => t.category === current.category);
  const rest = withTool.filter((t) => t.category !== current.category);
  const combined = sameCat.length >= 3 ? sameCat : [...sameCat, ...rest];
  return combined.slice(0, limit);
}

export const toolPagesByKind = (kind: 'tool' | 'model') =>
  toolPages.filter((p) => p.kind === kind);

export function getToolsForModel(modelSlug: string): ToolPageData[] {
  const model = toolPages.find((t) => t.slug === modelSlug && t.kind === 'model');
  if (!model) return [];
  const nameLower = model.modelName.toLowerCase();
  return toolPages.filter((t) => {
    if (t.kind !== 'tool' || !t.tool) return false;
    if (t.status === 'draft') return false;
    const tm = (t.tool.model ?? '').toLowerCase();
    const tmn = (t.tool.modelName ?? '').toLowerCase();
    return tm === modelSlug || tm.startsWith(modelSlug + '-') || tmn === nameLower || tmn.startsWith(nameLower);
  });
}

export function getModelForTool(tool: ToolPageData): ToolPageData | undefined {
  if (tool.kind !== 'tool' || !tool.tool) return undefined;
  const tm = (tool.tool.model ?? '').toLowerCase();
  const tmn = (tool.tool.modelName ?? '').toLowerCase();
  return toolPages.find((p) => {
    if (p.kind !== 'model') return false;
    if (p.status === 'draft') return false;
    const slug = p.slug.toLowerCase();
    const name = p.modelName.toLowerCase();
    return tm === slug || tm.startsWith(slug + '-') || tmn === name;
  });
}
